class VisTypeXyPlugin {
  constructor(initializerContext) {
    this.initializerContext = initializerContext;
  }
  async setup(core, {
    expressions,
    visualizations,
    charts
  }) {
    // eslint-disable-next-line no-console
    console.warn('The visTypeXy plugin is enabled\n\n', 'This may negatively alter existing vislib visualization configurations if saved.');
    const visualizationDependencies = {
      uiSettings: core.uiSettings,
      charts
    };
    const visTypeDefinitions = [];
    const visFunctions = [];
    visFunctions.forEach(fn => expressions.registerFunction(fn));
    visTypeDefinitions.forEach(vis => visualizations.createBaseVisualization(vis(visualizationDependencies)));
    return {};
  }
  start(core, deps) {
    // nothing to do here
  }
}

